function firstLine(p){const h=fs.openSync(p,'r');try{const b=Buffer.alloc(1048576),n=fs.readSync(h,b,0,b.length,0),s=b.subarray(0,n).toString('utf8'),e=s.search(/\r?\n/);return(e<0?s:s.slice(0,e)).replace(/^\uFEFF/,'')}finally{fs.closeSync(h)}}
function countSep(s,sep){let n=0,q=false;for(let i=0;i<s.length;i++){if(s[i]==='"'){if(q&&s[i+1]==='"')i++;else q=!q}else if(!q&&s[i]===sep)n++}return n}
function parseHeader(s,sep){const a=[];let v='',q=false;for(let i=0;i<s.length;i++){if(s[i]==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(!q&&s[i]===sep){a.push(v);v=''}else v+=s[i]}a.push(v);return a}
function source(fileName){const p=path.join(schemaLast,fileName),override=selection.schemaOverrides&&selection.schemaOverrides[fileName];let d,columns;if(override&&Array.isArray(override.columns)){d=override.delimiter||',';columns=override.columns}else if(fs.existsSync(p)){const h=firstLine(p);d=countSep(h,';')>countSep(h,',')?';':',';columns=parseHeader(h,d)}else throw new Error(`Missing selected CSV: ${p}`);if(columns.some(x=>!String(x).trim())||new Set(columns.map(x=>String(x).toLowerCase())).size!==columns.length)throw new Error(`Invalid header: ${fileName}`);return{fileName,tableName:path.parse(fileName).name,delimiter:d,columns}}
if(!Array.isArray(selection.includedFiles))throw new Error('source-selection.json has no includedFiles');
const sources=selection.includedFiles.map(source); if(new Set(sources.map(x=>x.tableName)).size!==sources.length)throw new Error('Duplicate table name');
function inside(p){const r=path.resolve(p);if(r!==root&&!r.startsWith(root+path.sep))throw new Error(`Outside workspace: ${r}`)}
function writeJson(p,v){inside(p);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,JSON.stringify(v,null,2).replace(/\n/g,'\r\n')+'\r\n','utf8')}
const mt=x=>`"${String(x).replace(/"/g,'""')}"`;
const ml=a=>`{${a.map(x=>Array.isArray(x)?ml(x):typeof x==='boolean'||typeof x==='number'?String(x):mt(x)).join(', ')}}`;
const parameter=(name,expression,type='Text')=>({name,kind:'m',expression,annotations:[{name:'IsParameterQuery',value:'True'},{name:'Type',value:type},{name:'IsParameterQueryRequired',value:'True'}]});
const expr=(name,expression)=>({name,kind:'m',expression});
const expressions=[
 parameter('SourceMode',mt('LocalFolder')),parameter('DataRootPath',mt(dataRoot)),parameter('SharePointSiteUrl',mt('')),parameter('SharePointDataFolderUrl',mt('')),parameter('HistoryMonths','24','Number'),parameter('HistoryMinRowRatio','0.5','Number'),
 expr('fnGetSourceFiles',String.raw`(relativeFolder as text) as table =>
let
 RelativeWindows=Text.Replace(relativeFolder,"/","\"), RelativeUrl=Text.Replace(relativeFolder,"\","/"),
 LocalPath=Text.TrimEnd(DataRootPath,{"\","/"})&"\"&RelativeWindows,
 Empty=#table(type table [Name=text,Content=binary,Extension=text,Folder Path=text,Date modified=nullable datetime,Size=nullable number],{}),
 LocalFiles=if SourceMode="LocalFolder" then Folder.Files(LocalPath) else Empty,
 SharePointFiles=if SourceMode="SharePoint" then let All=SharePoint.Files(SharePointSiteUrl,[ApiVersion=15]),Prefix=Text.TrimEnd(SharePointDataFolderUrl,{"/"})&"/"&RelativeUrl&"/" in Table.SelectRows(All,each Text.StartsWith([Folder Path],Prefix,Comparer.OrdinalIgnoreCase)) else Empty,
 Selected=if SourceMode="SharePoint" then SharePointFiles else LocalFiles
in Table.SelectColumns(Selected,{"Name","Content","Extension","Folder Path","Date modified","Size"},MissingField.UseNull)`),
 expr('fnToLogical',String.raw`(v as any) as nullable logical => let t=if v=null then null else Text.Lower(Text.Trim(Text.From(v))) in if v=null or t="" then null else if Value.Is(v,type logical) then v else if List.Contains({"true","1","yes","oui"},t) then true else if List.Contains({"false","0","no","non"},t) then false else null`),
 expr('fnToDateTime',String.raw`(v as any) as nullable datetime => if v=null or Text.Trim(Text.From(v))="" then null else try DateTime.From(v) otherwise try DateTime.FromText(Text.From(v),[Culture="en-US"]) otherwise try DateTime.FromText(Text.From(v),[Culture="fr-FR"]) otherwise null`),
 expr('fnToNumber',String.raw`(v as any) as nullable number => let t=if v=null then "" else Text.Trim(Text.From(v)), normalized=if Text.Contains(t,",") and not Text.Contains(t,".") then Text.Replace(t,",",".") else t in if t="" then null else try Number.FromText(normalized,"en-US") otherwise try Number.FromText(t,"fr-FR") otherwise null`),
 expr('fnToInt64',String.raw`(v as any) as nullable number => let n=fnToNumber(v) in if n=null then null else try Int64.From(n) otherwise null`),
 expr('fnLoadSourceTable',String.raw`(fileName as text,delimiter as text,expectedColumns as list,typeMap as list,includeHistory as logical) as table =>
let
 CurrentFiles=Table.Sort(Table.SelectRows(fnGetSourceFiles("DATA-LAST"),each [Name]=fileName),{{"Date modified",Order.Descending}}),
 Current=if Table.RowCount(CurrentFiles)=0 then error Error.Record("SmartInventorySourceMissing","Required CSV not found.",[FileName=fileName,SourceMode=SourceMode]) else CurrentFiles{0},
 CurrentModified=if Current[Date modified]=null then DateTime.LocalNow() else Current[Date modified], CurrentWeek=Date.StartOfWeek(Date.From(CurrentModified),Day.Monday),
 Parse=(item as record,isCurrent as logical) as table => let
  Csv=Csv.Document(Binary.Buffer(item[Content]),[Delimiter=delimiter,Encoding=65001,QuoteStyle=QuoteStyle.Csv]), Promoted=Table.PromoteHeaders(Csv,[PromoteAllScalars=true]), Base=Table.SelectColumns(Promoted,expectedColumns,MissingField.UseNull),
  Stamp=if item[Date modified]=null then CurrentModified else item[Date modified],
  A=Table.AddColumn(Base,"__SnapshotDate",each DateTime.From(Date.From(Stamp)),type datetime), B=Table.AddColumn(A,"__SnapshotDateTime",each Stamp,type datetime),
  C=Table.AddColumn(B,"__SnapshotPeriod",each Date.ToText(Date.StartOfWeek(Date.From(Stamp),Day.Monday),"yyyy-MM-dd"),type text), D=Table.AddColumn(C,"__IsCurrent",each isCurrent,type logical),
  E=Table.AddColumn(D,"__SourceFile",each fileName,type text), F=Table.AddColumn(E,"__SourceFolder",each item[Folder Path],type text)
 in F,
 Historical=if not includeHistory then #table({}, {}) else let
  Earliest=Date.AddMonths(Date.From(CurrentModified),-Number.RoundDown(HistoryMonths)), Candidates=Table.SelectRows(fnGetSourceFiles("DATA-ALL"),each [Name]=fileName and [Date modified]<>null and Date.From([Date modified])>=Earliest and Date.From([Date modified])<CurrentWeek and Text.Contains(Text.Replace([Folder Path],"\","/"),"/WeeklyHistory/",Comparer.OrdinalIgnoreCase)),
  WithPeriod=Table.AddColumn(Candidates,"__Period",each Date.ToText(Date.StartOfWeek(Date.From([Date modified]),Day.Monday),"yyyy-MM-dd"),type text), Grouped=Table.Group(WithPeriod,{"__Period"},{{"Latest",each Table.FirstN(Table.Sort(_,{{"Date modified",Order.Descending}}),1)}})
 in if Table.RowCount(Grouped)=0 then Candidates else Table.Combine(Grouped[Latest]),
 CurrentTable=Parse(Current,true), MinimumHistoryRows=Number.RoundDown(Table.RowCount(CurrentTable)*HistoryMinRowRatio), CandidateHistoryTables=if includeHistory and Table.RowCount(Historical)>0 then List.Transform(Table.ToRecords(Historical),each Parse(_,false)) else {}, HistoryTables=List.Select(CandidateHistoryTables,each Table.RowCount(_)>=MinimumHistoryRows), Combined=Table.Combine(List.Combine({HistoryTables,{CurrentTable}})),
 Typed=List.Accumulate(typeMap,Combined,(state as table,item as list)=>if not Table.HasColumns(state,item{0}) then state else if item{1}="logical" then Table.TransformColumns(state,{{item{0},fnToLogical,type nullable logical}}) else if item{1}="datetime" then Table.TransformColumns(state,{{item{0},fnToDateTime,type nullable datetime}}) else if item{1}="number" or item{1}="double" then Table.TransformColumns(state,{{item{0},fnToNumber,type nullable number}}) else if item{1}="int64" then Table.TransformColumns(state,{{item{0},fnToInt64,Int64.Type}}) else Table.TransformColumns(state,{{item{0},each if _=null then null else Text.From(_),type nullable text}}))
in Table.SelectColumns(Typed,List.Combine({expectedColumns,{"__SnapshotDate","__SnapshotDateTime","__SnapshotPeriod","__IsCurrent","__SourceFile","__SourceFolder"}}),MissingField.UseNull)`)
];
